428	// Resolves the outgoing edges of a node. Trigger, form and action nodes may
429	// name a single successor or a non-empty, duplicate-free array of successors;
430	// conditions keep their then/else pair and end nodes have none.
431	function normalizeSuccessors(node, nodes) {
432	  if (node.type === 'end') return [];
433	  if (node.type === 'condition') {
434	    for (const destination of [node.then, node.else]) {
435	      if (typeof destination !== 'string' || !nodes.has(destination)) {
436	        throw new Error(`node ${node.id} points to an unknown destination`);
437	      }
438	    }
439	    return [node.then, node.else];
440	  }
441	  const next = node.next;
442	  if (Array.isArray(next)) {
443	    if (next.length === 0) {
444	      throw new Error(`node ${node.id}: next array must not be empty`);
445	    }
446	    const seen = new Set();
447	    for (const destination of next) {
448	      if (typeof destination !== 'string') {
449	        throw new Error(`node ${node.id}: next array entries must be node id strings`);
450	      }
451	      if (seen.has(destination)) {
452	        throw new Error(`node ${node.id}: duplicate destination ${destination}`);
453	      }
454	      seen.add(destination);
455	      if (!nodes.has(destination)) {
456	        throw new Error(`node ${node.id} points to an unknown destination`);
457	      }
458	    }
459	    return [...seen];
460	  }
461	  if (typeof next !== 'string' || !nodes.has(next)) {
462	    throw new Error(`node ${node.id} points to an unknown destination`);
463	  }
464	  return [next];
465	}
