1105	  for (let attempt = 1; attempt <= retry.attempts; attempt += 1) {
1106	    if (signal && signal.aborted) {
1107	      return { ok: false, cancelled: true, error: lastReason };
1108	    }
1109	    const args = prepareArgs(attempt);
1110	    const record = createRecord(attempt);
1111	    let returned;
1112	    try {
1113	      returned = await invoke(...args);
1114	    } catch (error) {
1115	      lastReason = describeError(error);
1116	      record.error = lastReason;
1117	    }
1118	
1119	    // Clone first, then judge the clone: the isolation check must reflect
1120	    // exactly the content that will be saved. Inspecting the original return
1121	    // value would read enumerable getters an extra time (a getter that
1122	    // changes its answer between reads could swap ordinary saved content for
1123	    // later-appearing shared memory, or vice versa) and would iterate Map/Set
1124	    // through a possibly-overridden Symbol.iterator, while structuredClone
1125	    // reads the real internal entries. A return value whose normal reads
1126	    // throw, or that cannot be cloned at all, is the ordinary uncloneable
1127	    // failure — never an exception escaping the run.
1128	    if (record.error === null) {
1129	      try {
1130	        returned = structuredClone(returned);
1131	      } catch (error) {
1132	        lastReason = cloneFailureMessage;
1133	        record.error = lastReason;
1134	      }
1135	    }
1136	
1137	    if (record.error === null && containsSharedMemory(returned)) {
1138	      lastReason = sharedMemoryFailureMessage;
1139	      record.error = lastReason;
1140	    }
1141	
1142	    if (record.error === null) {
1143	      record.ok = true;
1144	      onSuccess(record, returned);
1145	      collect(record);
1146	      return { ok: true, value: returned };
1147	    }
1148	
1149	    // A cancellation observed while the attempt was in flight keeps the
1150	    // failure record but stops the retry loop: no wait, no next attempt —
1151	    // even when this was the last attempt the run could have made.
1152	    if (signal && signal.aborted) {
1153	      collect(record);
1154	      return { ok: false, cancelled: true, error: lastReason };
1155	    }
1156	
1157	    record.nextDelayMs = attempt < retry.attempts ? retryDelay(retry, attempt) : 0;
1158	    collect(record);
1159	    if (record.nextDelayMs > 0) {
1160	      // A cancellation during the wait ends it immediately; the failed
1161	      // attempt's record keeps its error but no longer promises a delay.
1162	      const interrupted = await sleep(record.nextDelayMs, signal);
1163	      if (interrupted) {
1164	        record.nextDelayMs = 0;
1165	        return { ok: false, cancelled: true, error: lastReason };
1166	      }
1167	    }
1168	  }
1169	
1170	  return { ok: false, error: lastReason };
1171	}
1172	
1173	// Runs one business action with retries. Every invocation receives fresh
1174	// structured clones of the current input and the successful outputs so far;
1175	// the stored success value is a clone independent of any object the
1176	// implementation keeps holding. The cancellation signal applies to this
1177	// loop only — compensation runs without one.
1178	async function runBusinessAction(node, binding, implementation, context, actionAttempts, signal) {
1179	  return runWithRetries({
1180	    retry: binding.retry,
1181	    signal,
1182	    prepareArgs: attempt => [structuredClone(context.input), structuredClone(context.output), node.id, attempt],
1183	    invoke: implementation,
1184	    createRecord: attempt => ({ nodeId: node.id, attempt, ok: false, error: null, nextDelayMs: 0 }),
1185	    cloneFailureMessage: `operation "${binding.name}" returned a value that cannot be structured-cloned`,
1186	    sharedMemoryFailureMessage: `operation "${binding.name}" returned a value that contains shared memory (SharedArrayBuffer or a typed array/DataView backed by one); independent copies cannot be guaranteed, so this return value is not supported`,
1187	    collect: record => actionAttempts.push(record),
1188	    onSuccess: () => {},
1189	  });
1190	}
1191	
1192	// Runs compensation for one already-succeeded business action. The call gets
1193	// independent structured clones of the input and earlier outputs captured at
1194	// the original action's success moment, the stored return value, the node id
1195	// and a 1-based compensation attempt number. Nothing here can touch the run
1196	// context, a later attempt, another run, or the stored success output.
1197	async function runCompensation(entry, implementation, records) {
1198	  const { nodeId, binding, snapshot } = entry;
1199	  return runWithRetries({
1200	    retry: binding.compensation.retry,
1201	    prepareArgs: attempt => [
1202	      structuredClone(snapshot.input), structuredClone(snapshot.output),
1203	      structuredClone(snapshot.result), nodeId, attempt,
1204	    ],
1205	    invoke: implementation,
1206	    createRecord: attempt => ({
1207	      nodeId, operation: binding.compensation.name, attempt,
1208	      ok: false, error: null, nextDelayMs: 0, result: null,
1209	    }),
1210	    cloneFailureMessage: `compensation "${binding.compensation.name}" returned a value that cannot be structured-cloned`,
1211	    sharedMemoryFailureMessage: `compensation "${binding.compensation.name}" returned a value that contains shared memory (SharedArrayBuffer or a typed array/DataView backed by one); independent copies cannot be guaranteed, so this return value is not supported`,
1212	    collect: record => records.push(record),
1213	    onSuccess: (record, returned) => { record.result = returned; },
1214	  });
1215	}
1216	
1217	// Undoes successful compensable business actions, most recent first, waiting
1218	// for each compensation to finish before starting the next. A compensation
1219	// that exhausts its retries is recorded as failed but earlier (still-pending)
1220	// actions are compensated regardless; neither the failed compensation nor the
1221	// original business operation is re-run. Compensating a node removes it from
1222	// the pending list exactly once — retried-then-succeeded actions and shared
1223	// join nodes were only recorded once to begin with.
1224	async function compensateRun(state, operations) {
1225	  const records = [];
1226	  let failed = false;
1227	  while (state.compensable.length > 0) {
1228	    const entry = state.compensable.pop();
1229	    const outcome = await runCompensation(entry, operations[entry.binding.compensation.name], records);
1230	    if (!outcome.ok) failed = true;
1231	  }
1232	  return { status: failed ? 'failed' : 'completed', attempts: records };
1233	}
1234	
1235	// Scheduling state shared by the synchronous and asynchronous execution
1236	// loops: activation, completion, dependency gating and the recorded end
1237	// result all behave identically; only business-action handling differs.
1238	function createRunState(nodes, workflow, input) {
1239	  const declarationOrder = [...nodes.values()];
1240	  const declarationIndex = new Map(declarationOrder.map((node, index) => [node.id, index]));
1241	  return {
1242	    trace: [],
1243	    actionAttempts: [],
1244	    context: { input: structuredClone(input), output: {} },
1245	    declarationOrder,
1246	    declarationIndex,
1247	    activated: new Set([workflow.entry]),
1248	    completed: new Set(),
1249	    endReached: false,
1250	    endResult: null,
1251	    // Successful business actions that declared a compensation, in the order
1252	    // they succeeded. Each entry keeps independent snapshots captured at the
1253	    // action's own success moment.
1254	    compensable: [],
1255	  };
1256	}
1257	
1258	function pickReadyNode(state) {
1259	  return state.declarationOrder.find(node =>
1260	    state.activated.has(node.id) && !state.completed.has(node.id)
1261	    && nodeDependencies.get(node).every(dependency => state.completed.has(dependency)));
1262	}
1263	
1264	function blockedResult(state) {
1265	  const waiting = state.declarationOrder.filter(node =>
1266	    state.activated.has(node.id) && !state.completed.has(node.id));
1267	  if (waiting.length === 0) return null;
1268	  return waiting.map(node => ({
1269	    nodeId: node.id,
1270	    missingDependencies: nodeDependencies.get(node)
1271	      .filter(dependency => !state.completed.has(dependency))
1272	      .sort((a, b) => state.declarationIndex.get(a) - state.declarationIndex.get(b)),
1273	  }));
1274	}
1275	
1276	// One shared scheduling step for the synchronous and asynchronous entries.
1277	// pickReadyNode already encodes activation plus dependency gating; this adds
1278	// the rules the two entries used to duplicate:
1279	// - a ready node is recorded in the trace the moment it enters execution, so
1280	//   waiting and never-activated nodes never appear in trace or output;
1281	// - an end node records its result and completes, but never stops the other
1282	//   activated branches — the caller simply loops again;
1283	// - with no ready node left, activated-but-waiting nodes classify the run as
1284	//   "blocked", a visited end node as "completed", and anything else is a
1285	//   structural cycle (validation rejects those before execution).
1286	// The terminal kinds are classifications only: each entry keeps building its
1287	// own result shape (the asynchronous one adds attempt and compensation
1288	// fields) so the public return values are unchanged.
1289	function advanceSchedule(state) {
1290	  const ready = pickReadyNode(state);
1291	  if (!ready) {
1292	    const waiting = blockedResult(state);
1293	    if (waiting) return { kind: 'blocked', waiting };
1294	    if (state.endReached) return { kind: 'completed' };
1295	    throw new Error('workflow did not terminate; a cycle is present');
1296	  }
1297	  state.trace.push({ nodeId: ready.id, type: ready.type });
1298	  if (ready.type === 'end') {
1299	    // Reaching an end node records the result but never stops other
1300	    // activated branches; the run completes once nothing can still run.
1301	    // Snapshot the result at this end node's own execution moment: the
1302	    // recorded value is this run's independent copy, so later mutation of
1303	    // the definition's result (during a wait on another activated branch),
1304	    // of another run's result, or of the returned value cannot reach back
1305	    // here. Validation already guarantees cloneability, so this cannot
1306	    // throw mid-run. An unset or null result stays null; 0, false and ""
1307	    // pass through ?? untouched (only null/undefined default to null).
1308	    state.endReached = true;
1309	    state.endResult = structuredClone(ready.result ?? null);
1310	    state.completed.add(ready.id);
1311	    return { kind: 'end' };
1312	  }
1313	  return { kind: 'run', node: ready };
1314	}
1315	
1316	// Applies a ready non-action node, mutating activation/completion state.
1317	// Returns an early-termination result (invalid_input / invalid_condition)
1318	// or null when execution should continue.
1319	function applyRegularNode(node, state) {
1320	  if (node.type === 'action') {
1321	    // Snapshot the legacy message at this action's own execution moment: the
1322	    // saved output is this run's independent deep copy, so editing nested
1323	    // fields, adding or deleting properties, or changing array members of the
1324	    // returned output never reaches the definition, another run, or an output
1325	    // this action recorded while another activated branch is still waiting.
1326	    // An unset, undefined or null message defaults to action:<node id>;
1327	    // "", 0 and false pass through untouched. Validation already guarantees
1328	    // that an explicit message is structured-cloneable, so this cannot throw
1329	    // mid-run.
1330	    const hasMessage = Object.hasOwn(node, 'message') && node.message !== undefined && node.message !== null;
1331	    const value = hasMessage ? structuredClone(node.message) : `action:${node.id}`;
1332	    setNodeOutput(state.context.output, node.id, value);
1333	  }
1334	  if (node.type === 'form') {
1335	    const compiled = formSchemas.get(node);
1336	    if (compiled) {
1337	      const formResult = processForm(node, state.context.input, compiled);
1338	      if (!formResult.ok) {
1339	        state.context.input = formResult.rollback;
1340	        return { status: 'invalid_input', context: state.context, trace: state.trace, errors: formResult.errors };
1341	      }
1342	    }
1343	  }
1344	  if (node.type === 'condition') {
1345	    const outcome = runCondition(compiledConditions.get(node), state.context.input, state.context.output, node.id);
1346	    if (!outcome.ok) {
1347	      return { status: 'invalid_condition', context: state.context, trace: state.trace, error: outcome.error };
1348	    }
1349	    state.activated.add(outcome.value ? node.then : node.else);
1350	  } else {
1351	    for (const target of successorTargets.get(node)) state.activated.add(target);
1352	  }
1353	  state.completed.add(node.id);
1354	  return null;
1355	}
1356	
1357	// Verifies, before a single node can run, that every business operation and
1358	// every compensation operation in the definition has a function registered —
1359	// including actions on untaken branches and entry-unreachable nodes.
1360	function resolveImplementation(operations, name, nodeId, kind) {
1361	  if (!isUsableObject(operations)
1362	    || !Object.hasOwn(operations, name)
1363	    || typeof operations[name] !== 'function') {
1364	    throw new Error(`action node ${nodeId}: ${kind} operation "${name}" has no function implementation; pass it to executeWorkflowAsync`);
1365	  }
1366	  return operations[name];
1367	}
1368	
1369	function verifyOperations(nodes, operations) {
1370	  for (const node of nodes.values()) {
1371	    const binding = actionBindings.get(node);
1372	    if (binding && binding.name !== null) {
1373	      resolveImplementation(operations, binding.name, node.id, 'business');
1374	    }
1375	    if (binding && binding.compensation !== null) {
1376	      resolveImplementation(operations, binding.compensation.name, node.id, 'compensation');
1377	    }
1378	  }
1379	}
1380	
1381	// The optional fourth argument of executeWorkflowAsync carries an
1382	// AbortSignal as `{ signal }`. Omitting it — or passing undefined, or an
1383	// options object without a signal — keeps the previous behavior; anything
1384	// else is a caller error reported before a single node executes.
1385	function resolveRunSignal(options) {
1386	  if (options === undefined) return null;
1387	  if (!isUsableObject(options)) {
1388	    throw new TypeError('executeWorkflowAsync options must be an object with an optional "signal" AbortSignal');
1389	  }
1390	  if (!Object.hasOwn(options, 'signal') || options.signal === undefined) return null;
1391	  const { signal } = options;
1392	  if (signal instanceof AbortSignal) return signal;
1393	  throw new TypeError('executeWorkflowAsync options.signal must be an AbortSignal');
1394	}
1395	
1396	export function executeWorkflow(workflow, input = {}) {
1397	  const nodes = validateWorkflow(workflow);
1398	  // Business operations are asynchronous: the synchronous entry must refuse
1399	  // a workflow that names any before a single node executes.
1400	  for (const node of nodes.values()) {
1401	    const binding = actionBindings.get(node);
1402	    if (binding && binding.name !== null) {
1403	      throw new Error(`action node ${node.id} names business operation "${binding.name}", which must run asynchronously; use executeWorkflowAsync instead of executeWorkflow`);
1404	    }
1405	  }
1406	
1407	  const state = createRunState(nodes, workflow, input);
1408	
1409	  for (;;) {
1410	    const step = advanceSchedule(state);
1411	
1412	    if (step.kind === 'blocked') {
1413	      return { status: 'blocked', context: state.context, trace: state.trace, blockedNodes: step.waiting };
1414	    }
1415	    if (step.kind === 'completed') {
1416	      return { status: 'completed', result: state.endResult, context: state.context, trace: state.trace };
1417	    }
1418	    if (step.kind === 'end') continue;
1419	
1420	    const early = applyRegularNode(step.node, state);
1421	    if (early) return early;
1422	  }
1423	}
1424	
1425	// Attaches compensation results to a failed run. Successful outputs and the
1426	// original terminal status stay untouched; compensation records live on
1427	// their own fields, never in the regular node trace.
1428	async function withCompensation(result, state, operations) {
1429	  const outcome = await compensateRun(state, operations);
1430	  result.compensationStatus = outcome.attempts.length === 0 ? 'not_needed' : outcome.status;
1431	  result.compensationAttempts = outcome.attempts;
1432	  return result;
1433	}
1434	
1435	// The cancelled terminal shape: the run stops where it is, keeps the
1436	// context, trace and attempt records produced so far, and never carries a
1437	// success result. Compensation for already-succeeded actions is attached by
1438	// withCompensation under the usual rules.
1439	function cancelledResult(state) {
1440	  return {
1441	    status: 'cancelled',
1442	    context: state.context,
1443	    trace: state.trace,
1444	    actionAttempts: state.actionAttempts,
1445	  };
1446	}
1447	
1448	export async function executeWorkflowAsync(workflow, input = {}, operations = {}, options = undefined) {
1449	  const signal = resolveRunSignal(options);
1450	  const nodes = validateWorkflow(workflow);
1451	  verifyOperations(nodes, operations);
1452	
1453	  const state = createRunState(nodes, workflow, input);
1454	
1455	  // A signal that is already aborted stops the run before the first node —
1456	  // but only after the definition and the operation registrations above have
1457	  // been checked. Nothing executes and nothing is compensated.
1458	  if (signal && signal.aborted) {
1459	    return withCompensation(cancelledResult(state), state, operations);
1460	  }
1461	
1462	  for (;;) {
1463	    // Once the signal fires, no new regular node runs and no new business
1464	    // action attempt starts; the run ends cancelled with whatever state it
1465	    // reached, even if an end node was already visited on another branch.
1466	    if (signal && signal.aborted) {
1467	      return withCompensation(cancelledResult(state), state, operations);
1468	    }
1469	
1470	    const step = advanceSchedule(state);
1471	
1472	    if (step.kind === 'blocked') {
1473	      // Unmet dependencies end the run; successful compensable actions are
1474	      // rolled back even though an end node may already have been reached.
1475	      return withCompensation({
1476	        status: 'blocked', context: state.context, trace: state.trace,
1477	        blockedNodes: step.waiting, actionAttempts: state.actionAttempts,
1478	      }, state, operations);
1479	    }
1480	    if (step.kind === 'completed') {
1481	      // A completed run never invokes compensation.
1482	      return {
1483	        status: 'completed', result: state.endResult, context: state.context,
1484	        trace: state.trace, actionAttempts: state.actionAttempts,
1485	        compensationStatus: 'not_needed', compensationAttempts: [],
1486	      };
1487	    }
1488	    if (step.kind === 'end') continue;
1489	
1490	    const ready = step.node;
1491	    if (ready.type === 'action') {
1492	      const binding = actionBindings.get(ready);
1493	      if (binding.name !== null) {
1494	        // Nodes execute one at a time in declaration order; awaiting here
1495	        // never lets another node jump ahead.
1496	        const actionResult = await runBusinessAction(
1497	          ready, binding, operations[binding.name], state.context, state.actionAttempts, signal);
1498	        if (!actionResult.ok) {
1499	          if (actionResult.cancelled) {
1500	            // Cancelled while the action was in flight or waiting to retry:
1501	            // the attempt records produced so far stay as they are.
1502	            return withCompensation(cancelledResult(state), state, operations);
1503	          }
1504	          // Retries are exhausted: stop immediately with prior input/output
1505	          // preserved, no output for this node and no successors activated —
1506	          // even if an end node was already reached — then compensate every
1507	          // earlier successful action that asked for it.
1508	          return withCompensation({
1509	            status: 'action_failed', nodeId: ready.id, attempts: binding.retry.attempts,
1510	            error: actionResult.error, context: state.context, trace: state.trace,
1511	            actionAttempts: state.actionAttempts,
1512	          }, state, operations);
1513	        }
1514	        // Capture the compensation snapshots from the state before the new
1515	        // output key lands: the action's own return value is handed to the
1516	        // compensation separately as its third argument.
1517	        const compensationSnapshot = binding.compensation === null ? null : {
1518	          input: structuredClone(state.context.input),
1519	          output: structuredClone(state.context.output),
1520	          result: structuredClone(actionResult.value),
1521	        };
1522	        setNodeOutput(state.context.output, ready.id, actionResult.value);
1523	        if (compensationSnapshot) {
1524	          // Each node completes at most once, so retried-then-successful
1525	          // actions and shared join nodes are scheduled for compensation
1526	          // exactly once.
1527	          state.compensable.push({ nodeId: ready.id, binding, snapshot: compensationSnapshot });
1528	        }
1529	        for (const target of successorTargets.get(ready)) state.activated.add(target);
1530	        state.completed.add(ready.id);
1531	        continue;
1532	      }
1533	    }
1534	
1535	    const early = applyRegularNode(ready, state);
1536	    if (early) {
1537	      early.actionAttempts = state.actionAttempts;
1538	      // A failed form (invalid_input) or failed condition evaluation
1539	      // (invalid_condition) ends normal execution and triggers compensation
1540	      // of the successful business actions that ran earlier.
1541	      return withCompensation(early, state, operations);
1542	    }
1543	  }
1544	}
