  assert.deepEqual(
    execution.actionAttempts.filter(r => r.nodeId === 'b')
      .map(r => [r.attempt, r.ok, r.nextDelayMs]),
    [[1, false, 20], [2, false, 40], [3, false, 0]],
  );
